preset.frame_eqs_eel:
wave_r = wave_r + 0.25*sin(1.4*time) + 0.25*sin(2.25*time);
wave_g = wave_g + 0.25*sin(1.7*time) + 0.25*sin(2.11*time);
wave_b = wave_b + 0.25*sin(1.84*time) + 0.25*sin(2.3*time);
warp = 0;

ob_r = ob_r + 0.3*sin(1.2*time);
ob_g = ob_g + 0.3*cos(2*time);
ob_b = ob_b + 0.25*sin(1.5*time);
ib_r = wave_r;
ib_b = wave_b;
ib_g = wave_g;

preset.pixel_eqs_eel:
thresh = above(bass_att,thresh)*2+(1-above(bass_att,thresh))*((thresh-1.3)*0.96+1.3);
dx_r = equal(thresh,2)*0.015*sin(5*time)+(1-equal(thresh,2))*dx_r;
dy_r = equal(thresh,2)*0.015*sin(6*time)+(1-equal(thresh,2))*dy_r;

rot = rot + 0.05*(2-rad)*(0.5*cos(rad-0.22*abs(ang*12+bass/time))*0.4-treb*1.3*cos(bass_att));
zoom = zoom - 0.02*abs(sin(bass-time/22*rad)-cos(0.3*bass-mid_att));
//zoom = zoom - 1.86*(0.5*(sin(time)-rad)*bass)*(bass/treb_att*0.2);
zoom = zoom - 0.2*abs(0.5*sin(0.2*bass*rot-3*(0.5-sin(0.5*time)-(0.25-rad))));
zoomexp = zoomexp + 0.25 + abs(0.5*sin(time*bass_att));
zoom = if(below(bass,0.05),0,zoom);
rot = if(below(bass,0.05),0,sin(0.2));
cy = cy + 0.25*sin(time)*22*dy_r;
cx = cx + 0.25*cos(2.5*time)*22*dx_r;
